export function assertPinnedPublicSha({ id, digest, registrySha, reportSha }) {
  const pin = Object.hasOwn(publicShaPins, id) ? publicShaPins[id] : null;
  if (!pin || ![digest, registrySha, reportSha].every(s => s === pin))
    throw new Error('Unrecognized public copy or jointly altered registry/report: ' + id);
  return true;
}
